BEGIN; INSERT INTO clinics(id,name,clerk_org_id) VALUES('ci-e20-a','CI E20 A','ci_e20_org_a'),('ci-e20-b','CI E20 B','ci_e20_org_b') ON CONFLICT(id) DO NOTHING; INSERT INTO ai_tool_policies(id,clinic_id,tool_key,interface_type,risk_tier,side_effect,approval_required,allowed_data_classes) VALUES('ci-e20-tool-a','ci-e20-a','synthetic.send_message','mcp',4,true,true,'["phi"]') ON CONFLICT(id) DO NOTHING; SET ROLE authenticated; SELECT set_config('app.clerk_org_id','ci_e20_org_a',false); DO 'BEGIN IF NOT EXISTS(SELECT 1 FROM ai_tool_policies WHERE id=''ci-e20-tool-a'') THEN RAISE EXCEPTION ''tenant A cannot read tool policy''; END IF; END'; SELECT set_config('app.clerk_org_id','ci_e20_org_b',false); DO 'BEGIN IF EXISTS(SELECT 1 FROM ai_tool_policies WHERE id=''ci-e20-tool-a'') THEN RAISE EXCEPTION ''cross-tenant tool policy read''; END IF; END'; RESET ROLE; ROLLBACK;